        final Parameter[] parameters = new Parameter[typeParameters.size()];
        int i = 0;
        for (TypeParameterElement e : typeParameters) {
          parameters[i] = new Parameter(i,
              e.getSimpleName().toString(),
              boundsFrom(e));
          i++;
