import static org.junit.jupiter.api.Assertions.assertThrows;

public class FoldFamiliesTest {
  @Test
  public void foldsBottomUpAndMemoizesByIdentity() {
    Lit one = ImmutableFoldFamilies.Lit.builder().value(1).build();
    Add shared = ImmutableFoldFamilies.Add.builder()
        .left(one)
        .optional(Optional.of(one))
        .addTerms(one)
        .addUniqueTerms(one)
        .addOccurrences(one)
